INSERT INTO _seed_neuro_ap1_context (unit_id,actor_id) SELECT curricular_unit_id,updated_by FROM quiz_topics WHERE id='quiz-topic-neuro-ap1' AND status='published' AND deleted_at IS NULL LIMIT 1;
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-038',unit_id,'quiz-topic-neuro-ap1','Que quatro ossos são visíveis na norma superior da calota?',NULL,'Esta vista é formada por quatro ossos articulados através de três suturas bem definidas. <strong>A parte escamosa do frontal situa-se anteriormente, a parte escamosa do occipital posteriormente e os dois parietais encontram-se na linha média entre ambos.</strong> A convexidade máxima de cada parietal é palpável ao nível da eminência parietal, especialmente evidente no sexo feminino.<p><small>Gray’s Anatomy, 42.ª ed., p. 560.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-038-answer','quiz-neuro-ap1-038','Frontal, dois parietais e occipital',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-038-incorrect','quiz-neuro-ap1-038','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-039',unit_id,'quiz-topic-neuro-ap1','Que sutura separa frontal e parietais?',NULL,'As linhas temporais superior e inferior passam próximo desta eminência, mas são mais bem observadas na norma lateral. A <strong>sutura coronal</strong> marca a articulação entre o bordo posterior do frontal e os bordos anteriores dos parietais. Desce pela calota e prolonga-se inferiormente até à região em que a asa maior do esfenóide se relaciona com a parte escamosa do temporal.<p><small>Gray’s Anatomy, 42.ª ed., p. 560.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-039-answer','quiz-neuro-ap1-039','Sutura coronal',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-039-incorrect','quiz-neuro-ap1-039','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-040',unit_id,'quiz-topic-neuro-ap1','Que sutura une os dois parietais na linha média?',NULL,'Desce pela calota e prolonga-se inferiormente até à região em que a asa maior do esfenóide se relaciona com a parte escamosa do temporal. A <strong>sutura sagital</strong> percorre a linha média entre os parietais e estende-se anteriormente desde a região do bregma até à região do lambda posteriormente. A sutura lambdóide delimita a articulação entre os bordos posteriores dos parietais e o bordo superior do occipital.<p><small>Gray’s Anatomy, 42.ª ed., p. 560.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-040-answer','quiz-neuro-ap1-040','Sutura sagital',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-040-incorrect','quiz-neuro-ap1-040','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-041',unit_id,'quiz-topic-neuro-ap1','Que sutura separa parietais e occipital?',NULL,'A sutura sagital percorre a linha média entre os parietais e estende-se anteriormente desde a região do bregma até à região do lambda posteriormente. A <strong>sutura lambdóide</strong> delimita a articulação entre os bordos posteriores dos parietais e o bordo superior do occipital. Um buraco parietal pode atravessar um ou ambos os parietais junto da sutura sagital, cerca de 3,5 cm anteriormente ao lambda.<p><small>Gray’s Anatomy, 42.ª ed., p. 560.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-041-answer','quiz-neuro-ap1-041','Sutura lambdóide',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-041-incorrect','quiz-neuro-ap1-041','Resposta não correspondente',2,0);
