INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-043',unit_id,'quiz-topic-neuro-ap1','Que acidente marca a convexidade máxima do parietal?',NULL,'A parte escamosa do frontal situa-se anteriormente, a parte escamosa do occipital posteriormente e os dois parietais encontram-se na linha média entre ambos. A convexidade máxima de cada parietal é palpável ao nível da <strong>eminência parietal</strong>, especialmente evidente no sexo feminino. As linhas temporais superior e inferior passam próximo desta eminência, mas são mais bem observadas na norma lateral.<p><small>Gray’s Anatomy, 42.ª ed., p. 560.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-043-answer','quiz-neuro-ap1-043','Eminência parietal',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-043-incorrect','quiz-neuro-ap1-043','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-044',unit_id,'quiz-topic-neuro-ap1','Que buraco inconstante pode existir junto da sutura sagital, anterior ao lambda?',NULL,'A sutura lambdóide delimita a articulação entre os bordos posteriores dos parietais e o bordo superior do occipital. Um <strong>buraco parietal</strong> pode atravessar um ou ambos os parietais junto da sutura sagital, cerca de 3,5 cm anteriormente ao lambda. Transmite uma pequena veia emissária relacionada com o seio sagital superior.<p><small>Gray’s Anatomy, 42.ª ed., p. 560.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-044-answer','quiz-neuro-ap1-044','Buraco parietal',1,1);
