INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-047',unit_id,'quiz-topic-neuro-ap1','Que ponto craniométrico ocupa a junção sagital-lambdóide?',NULL,'O bregma corresponde à junção das suturas coronal e sagital e assinala a posição da fontanela anterior. O <strong>lambda</strong> situa-se na junção das suturas sagital e lambdóide e corresponde à região da fontanela posterior. O vertex é o ponto mais elevado do crânio e encontra-se habitualmente no terço médio da sutura sagital.<p><small>Gray’s Anatomy, 42.ª ed., pp. 558–561; a lista de pontos segue o sumário oficial da AT1.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-047-answer','quiz-neuro-ap1-047','Lambda',1,1);
